CREATE TABLE IF NOT EXISTS b3_content_experience (
    experience_id VARCHAR(96) NOT NULL,
    tenant_id VARCHAR(64) NOT NULL,
    domain_code VARCHAR(32) NOT NULL,
    resource_type VARCHAR(64) NOT NULL,
    resource_key VARCHAR(96) NOT NULL,
    content_version_id BIGINT NOT NULL DEFAULT 301,
    availability VARCHAR(16) NOT NULL DEFAULT 'PUBLISHED',
    payload_json JSON NOT NULL,
    updated_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
    PRIMARY KEY (experience_id),
    UNIQUE KEY uk_b3_content_experience (tenant_id, domain_code, resource_type, resource_key),
    KEY idx_b3_content_experience_lookup (tenant_id, domain_code, resource_type, availability),
    CONSTRAINT chk_b3_content_experience_tenant CHECK (tenant_id = 'platform'),
    CONSTRAINT chk_b3_content_experience_availability CHECK (availability IN ('PUBLISHED', 'UNPUBLISHED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

